std::pair<double, array<int, 3>> RectLattice::distance(
  Position r, Direction u, const array<int, 3>& i_xyz) const
{
  // Compute each oncoming face distance once. Parallel directions and the
  // inactive z dimension of a 2D lattice cannot cause a crossing.
  int n = is_3d_ ? 3 : 2;
  array<double, 3> distances {INFTY, INFTY, INFTY};
  for (int i = 0; i < n; ++i) {
    if (u[i] != 0.0) {
      double edge = copysign(0.5 * pitch_[i], u[i]);
      distances[i] = (edge - r[i]) / u[i];
    }
  }
  double d = std::min({distances[0], distances[1], distances[2]});

  // Select faces using these same distances, rather than reconstructing the
  // hit position, whose roundoff can exceed an absolute spatial tolerance.
  // The minimum always participates (including d == 0). A relative tolerance
  // includes simultaneous edge/corner crossings independently of length scale
  // without merging distinct crossings merely because a direction is grazing.
  array<int, 3> lattice_trans {0, 0, 0};
  if (std::isfinite(d) && d < INFTY) {
    double tol = FP_PRECISION * std::abs(d);
    for (int i = 0; i < n; ++i) {
      if (distances[i] < INFTY && std::abs(distances[i] - d) <= tol) {
        lattice_trans[i] = copysign(1, u[i]);
      }
    }
  }

  return {d, lattice_trans};
}

